#include <DHT.h>

#define PIN_DHT 4
DHT dht(PIN_DHT, DHT22);
const int PIN_LDR = A0;
int pinLed = 9;

const int RAZMER_OKNA = 5;
float oknoTemperatury[RAZMER_OKNA];
int indeksOkna = 0;

unsigned long previousMillis = 0;
const long interval = 2000;

void vyvestiPokazanie(String nazvanie, float znachenie, String edinitsa) {
  Serial.print(nazvanie);
  Serial.print(": ");
  Serial.print(znachenie);
  Serial.println(edinitsa);
}

float sredneeMassiva(float arr[], int razmer) {
  float summa = 0;
  for (int i = 0; i < razmer; i = i + 1) {
    summa = summa + arr[i];
  }
  return summa / razmer;
}

void setup() {
  Serial.begin(9600);
  dht.begin();
  pinMode(pinLed, OUTPUT);
  for (int i = 0; i < RAZMER_OKNA; i = i + 1) {
    oknoTemperatury[i] = 0;
  }
}

void loop() {
  unsigned long currentMillis = millis();
  if (currentMillis - previousMillis >= interval) {
    previousMillis = currentMillis;

    float temperatura = dht.readTemperature();
    if (!isnan(temperatura)) {
      oknoTemperatury[indeksOkna] = temperatura;
      indeksOkna = (indeksOkna + 1) % RAZMER_OKNA;
    }
    float srednyayaTemperatura = sredneeMassiva(oknoTemperatury, RAZMER_OKNA);

    int svetSyroe = analogRead(PIN_LDR);
    int svetProcent = map(svetSyroe, 0, 1023, 0, 100);

    String status;
    if (srednyayaTemperatura > 35 || srednyayaTemperatura < 0) {
      status = "Авария";
      digitalWrite(pinLed, HIGH);
    } else if ((srednyayaTemperatura > 28 && srednyayaTemperatura <= 35) || svetProcent < 10) {
      status = "Предупреждение";
      digitalWrite(pinLed, LOW);
    } else {
      status = "Норма";
      digitalWrite(pinLed, LOW);
    }

    vyvestiPokazanie("Температура", temperatura, " C");
    vyvestiPokazanie("Средняя температура", srednyayaTemperatura, " C");
    vyvestiPokazanie("Освещённость", svetProcent, " %");
    Serial.print("Статус: ");
    Serial.println(status);
    Serial.println("----------");
  }
}
